// ─── 보스 격파 에필로그 — 지구 해방 엔딩 (격정적 대사 → onDone 콜백) ─
// 우르사 메이저 단말마 → 백구·주인공 격정 대사 → 지구 해방 선언으로 완벽 마무리
// ※ 보이드/추가 컨텐츠 언급 제거 — 우르사 메이저 격파가 진정한 엔딩
function showBossVictoryEpilogue(onDone){
  const cmdName=G.profile?.name||'사령관';
  const lines=[
    {sp:'우르사 메이저',tx:'... 불가능... 한낱 인간들의 함대가... 100년의 봉인을... 깨버렸단 말인가...'},
    {sp:'우르사 메이저',tx:'...크윽... 인정하지... 너희에게는 — 우리가 갖지 못한 그 무엇이 있었다...'},
    {sp:'우르사 메이저',tx:'고향으로... 돌아가야 할 이유. 인류의... 그 강한 의지... 그것이 우리를... 무너뜨렸다...'},
    {sp:'시스템',tx:'💥 적 기함 우르사 메이저 — 코어 붕괴 확인. 친위대 전멸. 워프 신호 소실.'},
    {sp:'백구',tx:`${cmdName}!! 해냈어! 진짜로 해냈어!! 100년이야, 100년!! 폐지 줍던 내가 이 순간을 보다니!!`},
    {sp:'백구',tx:'지구 봉쇄가 풀린다! 통신 신호가 들어와! 가족들이... 사람들이... 다시 별을 본대!'},
    {sp:'시스템',tx:'📡 지구 통신망 복구. 전 인류로부터의 환호가 은하 전체로 송신되고 있습니다.'},
    {sp:cmdName,tx:'...드디어 끝났다. 100년의 침묵, 100년의 굴종 — 오늘 우리 손으로 청산했다.'},
    {sp:cmdName,tx:'고생했다, 전 함대. 영웅들, 크루들 — 너희 모두의 이름은 인류 역사에 영원히 새겨질 것이다.'},
    {sp:'백구',tx:`${cmdName}! 우리 진짜 영웅이야! 100년 만에 자유로워진 지구가 우리 사령관을 부르고 있어!`},
    {sp:cmdName,tx:'우리는 인류의 길을 열었다. 이제부터 별들은 우리의 친구다 — 그리고 지구는, 영원히 자유다.'},
    {sp:'시스템',tx:'🌍 지구 봉쇄 완전 해제. 인류 해방 선언. — DESTINATION EARTH 완수.'}
  ];
  let _idx=0;
  function _renderLine(){
    const l=lines[_idx];
    const isFinal=_idx===lines.length-1;
    const isUrsa=l.sp==='우르사 메이저';
    const isSys=l.sp==='시스템';
    const isBaekgu=l.sp==='백구';
    const spColor=isUrsa?'#ff3366':isSys?'#66ffcc':isBaekgu?'var(--cyan)':'var(--gold)';
    const spIc=isUrsa?'💀':isSys?'⚡':isBaekgu?'🐕':'⚑';
    const portrait=charPortraitHTML(l.sp,spIc,216,spColor);
    // 배경 그라데이션: 우르사=어두운 적색 / 시스템=황금 / 그 외=영광스러운 분위기
    const bgGrad=isUrsa
      ?'linear-gradient(135deg,rgba(80,10,10,.85),rgba(15,2,2,.95))'
      :isSys
        ?'linear-gradient(135deg,rgba(255,215,0,.15),rgba(20,30,40,.85))'
        :'linear-gradient(135deg,rgba(40,80,140,.25),rgba(10,15,30,.9))';
    const borderColor=isUrsa?'rgba(255,80,80,.6)':isSys?'rgba(255,215,0,.55)':'rgba(120,180,255,.5)';
    openModal(I18N.t('modal.finalEpilogue'),
      `<div style="padding:14px;min-height:240px">
        <div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;justify-content:center;margin-bottom:14px;padding:16px;background:${bgGrad};border:1.5px solid ${borderColor};border-radius:12px;box-shadow:0 0 24px ${borderColor}">
          ${portrait}
          <div style="flex:1">
            <div style="font-size:13px;color:${spColor};font-weight:bold;margin-bottom:6px;letter-spacing:1.5px">${l.sp}</div>
            <div style="font-size:17px;color:var(--yellow);line-height:1.85;word-break:keep-all;text-shadow:0 1px 2px rgba(0,0,0,.6)">"${l.tx}"</div>
          </div>
        </div>
        <div style="text-align:center;font-size:11px;color:var(--dim);letter-spacing:2px">${_idx+1} / ${lines.length}</div>
      </div>`,
      [
        isFinal
          ? {txt:'🎊 보상 확인 ▶',fn:()=>{closeModal();if(typeof onDone==='function')onDone();},cls:'btn-gold'}
          : {txt:I18N.t('ui.continueArrow'),fn:()=>{_idx++;_renderLine();},cls:'btn-gold'}
      ]
    );
  }
  _renderLine();
}

// ─── 보스 격파 특별 셀레브레이션 팝업 (지구 해방 선언) ──────────
function showBossCelebration(onDone){
  const cmdName=G.profile?.name||'사령관';
  const co=G.profile?.company||'은하상단';
  const turn=G.turn||0;
  // 함대 통계
  const fleetCount=(G.fleet||[]).length;
  const heroCount=(G.heroes||[]).length;
  const survivors=(G.fleet||[]).filter(s=>s.hp>0).length;
  const html=`
    <div style="padding:22px 18px;text-align:center;background:radial-gradient(ellipse at center,rgba(20,20,60,.6),rgba(0,0,0,.95));border-radius:8px">
      <div style="font-size:64px;margin-bottom:8px;animation:pulse 1.4s infinite;text-shadow:0 0 30px gold,0 0 60px gold">🌍</div>
      <div style="font-size:30px;font-weight:bold;background:linear-gradient(90deg,#ffd700,#ff66cc,#66ffff,#ffd700);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;letter-spacing:8px;margin-bottom:6px;background-size:200% 100%;animation:shimmer 3s linear infinite">${I18N.t('ui.earthFreedom')}</div>
      <div style="font-size:13px;color:var(--cyan);letter-spacing:3px;margin-bottom:18px">EARTH LIBERATED · 100Y SIEGE ENDED</div>
      <div style="display:flex;justify-content:space-around;flex-wrap:wrap;gap:14px;margin:18px 0;padding:14px;background:rgba(255,215,0,.06);border:1px solid rgba(255,215,0,.3);border-radius:10px">
        <div><div style="font-size:11px;color:var(--dim)">${I18N.t('ui.turnsRequired')}</div><div style="font-size:22px;color:var(--gold);font-weight:bold">${turn}</div></div>
        <div><div style="font-size:11px;color:var(--dim)">${I18N.t('ui.shipsAlive')}</div><div style="font-size:22px;color:#66ff99;font-weight:bold">${survivors}/${fleetCount}</div></div>
        <div><div style="font-size:11px;color:var(--dim)">${I18N.t('ui.recruitedHeroes2')}</div><div style="font-size:22px;color:#ff99ff;font-weight:bold">${heroCount}</div></div>
        <div><div style="font-size:11px;color:var(--dim)">${I18N.t('ui.gainedCredits')}</div><div style="font-size:22px;color:var(--gold);font-weight:bold">₡${(G.credits||0).toLocaleString()}</div></div>
      </div>
      <div style="font-size:15px;color:var(--yellow);line-height:1.8;margin:14px 0;padding:14px;background:rgba(255,255,255,.02);border-left:3px solid var(--gold);text-align:left">
        ${co} 총사령관 <b style="color:var(--gold)">${cmdName}</b>의 함대가<br>
        은하의 봉쇄자 <b style="color:#ff3366">우르사 메이저</b>를 격파하였습니다.<br><br>
        100년 동안 침묵했던 지구가 마침내 다시 별을 향해 손을 뻗습니다.<br>
        인류는 자유를 되찾았고, 우주는 다시 인류의 무대가 되었습니다.<br><br>
        <span style="color:#ffd700;font-weight:bold">— 인류의 운명을 지킨 그대, 사령관 ${cmdName}에게 영광을 —</span>
      </div>
      <div style="font-size:13px;color:var(--gold);margin-top:18px;letter-spacing:4px;text-shadow:0 0 12px rgba(255,215,0,.5)">— THE END —</div>
      <div style="font-size:11px;color:var(--dim);margin-top:6px;letter-spacing:3px">— DESTINATION EARTH —</div>
    </div>
    <style>
      @keyframes shimmer{0%{background-position:0% 50%}100%{background-position:200% 50%}}
    </style>`;
  openModal(I18N.t('modal.victoryDeclaration'),html,
    [{txt:'🎁 전투 보고서 확인 ▶',fn:()=>{closeModal();if(typeof onDone==='function')onDone();},cls:'btn-gold'}],
    {bossfight:true}
  );
  try{AudioMgr.playSfx('coin',{vol:0.9,cooldown:0});}catch(e){}
  try{AudioMgr.playSfx('notify',{vol:0.9,cooldown:0});}catch(e){}
}

// ─── 엔딩 시퀀스: 어두운 화면 → 영웅/주인공 대사 흘러가기 → 스크롤 크레딧 ───
// onDone: 엔딩 종료 후 콜백 (보이드 페이즈 진입)
// ─── ACT 5 최종 엔딩 크레딧 ─────────────────────────────────────
// 보이드의 심연 통과 후 — 스토리 정리 + 제작진 + 영웅 + AI 이미지 + Special thanks
function showFinalEndingCredits(){
  // 크레딧 진입 — 잔여 전투 SFX/이펙트 차단
  try{if(typeof combatState!=='undefined'&&combatState)combatState.done=true;}catch(e){}
  try{AudioMgr.stopAllSfx();}catch(e){}
  try{if(typeof _cbEffects!=='undefined')_cbEffects=[];}catch(e){}
  const cmdName=G.profile?.name||'사령관';
  const co=G.profile?.company||'은하상단';
  const _hl=G.heroes||[];
  const HERO_NAMES={H01:'이순신',H02:'장영실',H03:'광개토대왕',H04:'유리 가가린',H05:'호레이쇼 넬슨',H06:'아인슈타인',H07:'니콜라 테슬라',H08:'마르코 폴로'};
  const heroList=_hl.map(h=>HERO_NAMES[h]||h).filter(Boolean);
  const overlay=document.createElement('div');
  overlay.id='_final-ending-overlay';
  overlay.style.cssText=[
    'position:fixed','left:0','top:0','right:0','bottom:0','width:100vw','height:100vh',
    'background:#000','z-index:99999','opacity:0','transition:opacity 2.5s ease-in',
    'display:flex','align-items:flex-start','justify-content:center',
    'pointer-events:auto','color:#fff','font-family:Malgun Gothic, sans-serif','overflow:hidden'
  ].join(';');
  overlay.innerHTML=`
    <style>
      @keyframes _finalRoll{from{transform:translateY(100vh)}to{transform:translateY(-220%)}}
      @keyframes _finalShim{0%{background-position:0% 50%}100%{background-position:200% 50%}}
      @keyframes _finalStars{from{background-position:0 0}to{background-position:-2000px 0}}
    </style>
    <!-- 별 배경 -->
    <div style="position:absolute;inset:0;background:radial-gradient(2px 2px at 20% 30%,#fff,transparent),radial-gradient(1px 1px at 60% 70%,#fff,transparent),radial-gradient(1px 1px at 80% 10%,#fff,transparent),radial-gradient(2px 2px at 30% 80%,#fff,transparent),radial-gradient(1px 1px at 90% 50%,#fff,transparent);background-size:200px 200px;opacity:.4;animation:_finalStars 60s linear infinite"></div>
    <!-- 크레딧 롤 -->
    <div id="_final-credits" style="position:relative;width:100%;max-width:760px;text-align:center;padding:20px;animation:_finalRoll 90s linear forwards;color:#fff">
      <div style="height:30vh"></div>

      <div style="font-size:36px;letter-spacing:14px;margin-bottom:12px;background:linear-gradient(90deg,#ffd700,#ff66cc,#66ffff,#ffd700);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;background-size:200% 100%;animation:_finalShim 4s linear infinite">DESTINATION EARTH</div>
      <div style="font-size:14px;color:#aaa;letter-spacing:10px;margin-bottom:80px">— ACT 5 · 종막 —</div>

      <!-- 스토리 정리 -->
      <div style="color:#ffd700;font-size:14px;letter-spacing:6px;margin-bottom:14px">— 그동안의 여정 —</div>
      <div style="font-size:15px;line-height:2.2;color:#dde;text-align:left;background:rgba(255,255,255,.03);padding:24px 28px;border-radius:8px;border:1px solid rgba(255,215,0,.15);margin-bottom:60px;word-break:keep-all">
        <p style="margin:0 0 14px"><b style="color:#ffd700">ACT 1</b> — 100년의 봉쇄. 우르사 메이저 함대가 지구를 둘러쌌고, 위장 상단 ${co}이(가) 폐지를 주워가며 함대를 일군다. 백구가 ${cmdName}을(를) 깨운다.</p>
        <p style="margin:0 0 14px"><b style="color:#ffaa44">ACT 2</b> — 일곱 팩션의 우주. 수퍼비아, 아우레우스, 메카니카, 크리그, 치크스, 지구 저항군, 보이드. ${cmdName}은(는) 무역과 전투로 함대를 키우고, 전설의 영웅 ${heroList.length}명을 영입한다.</p>
        <p style="margin:0 0 14px"><b style="color:#ff66ff">ACT 3</b> — 균열의 너머. 보이드 행성에서 미지의 신호가 잡힌다. 보이드 크리스탈을 모으며 최종전을 준비한다.</p>
        <p style="margin:0 0 14px"><b style="color:#ff4444">ACT 4</b> — 지구 해방. 우르사 메이저 격파. 100년의 봉쇄가 끝나고, 인류는 다시 우주로 나간다.</p>
        <p style="margin:0 0 14px"><b style="color:#cc66ff">ACT 5</b> — 보이드의 심연. 1000년의 침묵을 깬 블랙팔콘과의 결투. 모든 시련을 견뎌낸 사령관은 은하 가운데 블랙홀로 들어간다.</p>
        <p style="margin:0;color:#aaa;font-style:italic">"누구도 여기서 살아서 나가지 못한다.<br>네가 원하는걸 해라."</p>
      </div>

      <!-- 등장 인물 -->
      <div style="color:#66ddff;font-size:14px;letter-spacing:6px;margin-bottom:10px">${I18N.t('ui.commanderTitle')}</div>
      <div style="font-size:24px;margin-bottom:40px;color:#fff">${cmdName} <span style="color:#aaa;font-size:14px;margin-left:6px">— ${co}</span></div>

      <div style="color:#66ddff;font-size:14px;letter-spacing:6px;margin-bottom:10px">전속 AI</div>
      <div style="font-size:20px;margin-bottom:40px">🐕 백구 — AI 진돗개</div>

      ${heroList.length>0?`
        <div style="color:#ff99ff;font-size:14px;letter-spacing:6px;margin-bottom:10px">영입 영웅 (${heroList.length}/8명)</div>
        <div style="font-size:17px;line-height:2;margin-bottom:40px">
          ${heroList.map(n=>`<div>⭐ ${n}</div>`).join('')}
        </div>
      `:''}

      <div style="color:#cc66ff;font-size:14px;letter-spacing:6px;margin-bottom:10px">${I18N.t('ui.finalBoss')}</div>
      <div style="font-size:17px;line-height:1.9;margin-bottom:40px">
        💀 ${I18N.t('speaker.ursaMajor')} — ${I18N.t('credits.ursaDesc')}<br>
        🌑 ${I18N.t('speaker.blackfalcon')} — ${I18N.t('credits.blackfalconDesc')}
      </div>

      <!-- 함대 통계 -->
      <div style="color:#66ff99;font-size:14px;letter-spacing:6px;margin-bottom:10px">${I18N.t('ui.fleetStats')}</div>
      <div style="font-size:15px;color:#fff;line-height:2;margin-bottom:60px">
        소요 턴: <b style="color:#ffd700">${G.turn||0}</b><br>
        영웅 영입: <b style="color:#ff99ff">${heroList.length}/8</b><br>
        행성 보유: <b style="color:#66ddff">${Object.values(G.planets||{}).filter(p=>p.owned).length}/30</b><br>
        최종 크레딧: <b style="color:#ffd700">₡${(G.credits||0).toLocaleString()}</b><br>
        난이도: <b style="color:#fff">${({easy:I18N.t('difficulty.easy'),normal:I18N.t('difficulty.normal'),hard:I18N.t('difficulty.hard'),extreme:I18N.t('difficulty.extreme')})[G.difficulty]||I18N.t('difficulty.normal')}</b>
      </div>

      <!-- 제작진 -->
      <div style="color:#ffd700;font-size:14px;letter-spacing:6px;margin-bottom:10px">${I18N.t('ui.credits')}</div>
      <div style="font-size:16px;line-height:2;margin-bottom:40px">
        기획·디자인 · ${co}<br>
        개발 · Destination Earth Team<br>
        AI 협업 · Claude (Anthropic)
      </div>

      <!-- AI 이미지 제작 -->
      <div style="color:#cc66ff;font-size:14px;letter-spacing:6px;margin-bottom:10px">AI 이미지 제작</div>
      <div style="font-size:16px;line-height:2;margin-bottom:40px">
        이규빈 · 나노바나나 · 미드저니
      </div>

      <!-- Special Thanks -->
      <div style="color:#ffd700;font-size:14px;letter-spacing:6px;margin-bottom:10px">Special Thanks</div>
      <div style="font-size:16px;line-height:2;margin-bottom:14px">
        ${I18N.t('credits.specialThanksCompany')}
      </div>
      <div style="font-size:14px;line-height:1.9;color:#bbb;margin-bottom:60px;font-style:italic">
        ${I18N.t('credits.testerThanks')}
      </div>

      <div style="font-size:14px;color:#666;margin-bottom:8px">— 그리고 모든 인류에게 —</div>
      <div style="font-size:24px;color:#fff;letter-spacing:8px;margin-bottom:80px">${I18N.t('ui.thankYou')}</div>

      <div style="font-size:13px;color:#444;letter-spacing:4px">— THE END —</div>
      <div style="font-size:12px;color:#333;letter-spacing:2px;margin-top:8px">ACT 5 · 보이드의 심연</div>
      <div style="height:30vh"></div>
    </div>
    <!-- 건너뛰기 (우측 하단, 항상 노출) -->
    <button id="_final-skip" style="position:absolute;right:24px;bottom:24px;padding:10px 22px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.3);color:#fff;border-radius:6px;cursor:pointer;font-size:13px;letter-spacing:2px;z-index:10">건너뛰기 →</button>
    <!-- 크레딧 종료 후 표시될 메인 복귀 버튼 (중앙) -->
    <button id="_final-return" style="position:absolute;left:50%;bottom:60px;transform:translateX(-50%);padding:18px 52px;background:linear-gradient(135deg,rgba(255,215,0,.18),rgba(255,150,80,.22));border:2px solid #ffd700;color:#ffd700;border-radius:10px;cursor:pointer;font-size:18px;font-weight:bold;letter-spacing:6px;z-index:11;box-shadow:0 0 40px rgba(255,215,0,.45),inset 0 0 20px rgba(255,215,0,.1);display:none;opacity:0;transition:opacity 1.5s ease-in" onmouseover="this.style.background='linear-gradient(135deg,rgba(255,215,0,.32),rgba(255,150,80,.34))';this.style.transform='translateX(-50%) translateY(-2px)'" onmouseout="this.style.background='linear-gradient(135deg,rgba(255,215,0,.18),rgba(255,150,80,.22))';this.style.transform='translateX(-50%)'">🌍 게임으로 돌아가기</button>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(()=>{overlay.style.opacity='1';});
  const _close=()=>{
    overlay.style.transition='opacity 1.5s ease-out';
    overlay.style.opacity='0';
    setTimeout(()=>{
      try{overlay.remove();}catch(e){}
      try{AudioMgr.playBgm(_planetBgmName(G.currentPlanet));}catch(e){}
      try{setHubNav('main');hubTab('main');}catch(e){}
    },1500);
  };
  overlay.querySelector('#_final-skip').onclick=_close;
  overlay.querySelector('#_final-return').onclick=_close;
  // 90초(크레딧 롤 종료) 후 자동 종료 대신 "게임으로 돌아가기" 버튼 노출
  setTimeout(()=>{
    const rb=overlay.querySelector('#_final-return');
    if(rb){rb.style.display='block';requestAnimationFrame(()=>{rb.style.opacity='1';});}
    // 건너뛰기 버튼은 작게 유지하되 라벨 변경
    const sb=overlay.querySelector('#_final-skip');
    if(sb)sb.textContent='닫기 →';
  },90000);
}
try{if(typeof window!=='undefined')window.showFinalEndingCredits=showFinalEndingCredits;}catch(e){}

function showEndingCredits(onDone){
  // 엔딩 진입 — 전투 SFX/이펙트 차단
  try{if(typeof combatState!=='undefined'&&combatState)combatState.done=true;}catch(e){}
  try{AudioMgr.stopAllSfx();}catch(e){}
  try{if(typeof _cbEffects!=='undefined')_cbEffects=[];}catch(e){}
  const cmdName=G.profile?.name||'사령관';
  const co=G.profile?.company||'은하상단';
  const shipName=G.profile?.ship||'머스탱';
  // 신화 기함 호칭: 사용자가 함선명을 커스텀했으면 "{함선}(거북선급)", 아니면 원작의 "위대한 화랑"
  const flagshipName=(shipName&&shipName!=='머스탱')?(shipName+'(거북선급)'):'위대한 화랑';
  // 영입한 영웅별 마무리 대사 + 백구의 일기 페이지
  // 일기는 영웅 카드 직후 한 페이지씩 회상되며 흐른다.
  const _hl=G.heroes||[];
  const heroEndings=[];   // (크레딧 롤 명단용)
  const heroBlocks=[];    // (대사 + 일기 페어 — 화면 시퀀스용)
  const BG={sp:'백구의 일기',col:'#9ee7ff',ic:'📓'};
  function _bgPage(tx){return Object.assign({tx},BG);}
  if(_hl.includes('H01')){
    heroEndings.push({nm:'이순신',ic:'⚔️',col:'#ffd700',tx:'조선의 하늘이 아니군. 하지만… 인류의 하늘이오.'});
    heroBlocks.push({sp:'이순신',col:'#ffd700',ic:'⚔️',tx:'조선의 하늘이 아니군. 하지만… 인류의 하늘이오.'});
    heroBlocks.push(_bgPage(`이순신을 깨운 날. 첫 마디는 "지구는?"이었다.\n"이겨야 하는 싸움입니다."`));
  }
  if(_hl.includes('H02')){
    heroEndings.push({nm:'장영실',ic:'⚙️',col:'#9ee7ff',tx:'거북선이… 돌아왔구나. 내가 만든 배가 지구를 구했어.'});
    heroBlocks.push({sp:'장영실',col:'#9ee7ff',ic:'⚙️',tx:'거북선이… 돌아왔구나. 내가 만든 배가 지구를 구했어.'});
    heroBlocks.push(_bgPage(`장영실. ${flagshipName}의 도면을 펼치자 그의 눈이 100년 만에 흔들렸다.`));
  }
  if(_hl.includes('H03')){
    heroEndings.push({nm:'광개토대왕',ic:'⚔️',col:'#ff6644',tx:'정복자는 땅을 빼앗는다. 그러나 진정한 왕은 땅을 돌려준다. 오늘 나는 땅을 돌려줬소.'});
    heroBlocks.push({sp:'광개토대왕',col:'#ff6644',ic:'⚔️',tx:'정복자는 땅을 빼앗는다. 그러나 진정한 왕은 땅을 돌려준다. 오늘 나는 땅을 돌려줬소.'});
    heroBlocks.push(_bgPage(`"1,700년." 광개토대왕의 첫 말. 내 100년이 짧아졌다.\n그는 ${cmdName}을(를) "땅을 되찾아준 자"라고 불렀다.`));
  }
  if(_hl.includes('H04')){
    heroEndings.push({nm:'유리 가가린',ic:'🚀',col:'#66ddff',tx:'Поехали로 처음 올라갔을 때, 창밖으로 지구가 보였어요. 지금 다시 보니… 여전히 아름답군요.'});
    heroBlocks.push({sp:'유리 가가린',col:'#66ddff',ic:'🚀',tx:'Поехали로 처음 올라갔을 때, 창밖으로 지구가 보였어요. 지금 다시 보니… 여전히 아름답군요.'});
    heroBlocks.push(_bgPage(`가가린은 우주에서 처음 본 지구를 평생 그리워했다.\n나는 처음 본 풀밭을 그리워하게 될 것 같다.`));
  }
  if(_hl.includes('H05')){
    heroEndings.push({nm:'호레이쇼 넬슨',ic:'⚓',col:'#aaffaa',tx:'내가 지킨 바다는 영국 앞바다였소. 이번엔 온 우주를 지켰군. England expects. 지구가 기대했고, 우리가 해냈소.'});
    heroBlocks.push({sp:'호레이쇼 넬슨',col:'#aaffaa',ic:'⚓',tx:'내가 지킨 바다는 영국 앞바다였소. 이번엔 온 우주를 지켰군. England expects. 지구가 기대했고, 우리가 해냈소.'});
    heroBlocks.push(_bgPage(`넬슨과 이순신. 두 제독은 그저 손을 내밀었다.\n200년의 시차를 한 손바닥이 메웠다.`));
  }
  if(_hl.includes('H06')){
    heroEndings.push({nm:'아인슈타인',ic:'🧠',col:'#cc99ff',tx:`100년의 계산이 맞았습니다. 그리고 계산에 없던 것 하나 — ${cmdName}과(와) 백구의 그 대화. 그건 방정식으로 예측 못 했어요. 인간의 것이니까요.`});
    heroBlocks.push({sp:'아인슈타인',col:'#cc99ff',ic:'🧠',tx:`100년의 계산이 맞았습니다. 그리고 계산에 없던 것 하나 — ${cmdName}과(와) 백구의 그 대화. 그건 방정식으로 예측 못 했어요. 인간의 것이니까요.`});
    heroBlocks.push(_bgPage(`이휘소 박사님이 나를 만들었다는 사실을 안 날.\n"고독" 어떤 정의도 100년을 담지 못했다.`));
  }
  if(_hl.includes('H07')){
    heroEndings.push({nm:'니콜라 테슬라',ic:'⚡',col:'#66ffff',tx:'전류는 흐를 곳을 찾아요. 우리는 드디어 흐를 곳을 찾았습니다. 집으로.'});
    heroBlocks.push({sp:'니콜라 테슬라',col:'#66ffff',ic:'⚡',tx:'전류는 흐를 곳을 찾아요. 우리는 드디어 흐를 곳을 찾았습니다. 집으로.'});
    heroBlocks.push(_bgPage(`테슬라의 1Hz. 0.3mm와 1Hz — 100년을 잠그던 자물쇠였다.`));
  }
  if(_hl.includes('H08')){
    heroEndings.push({nm:'마르코 폴로',ic:'🧭',col:'#ffcc66',tx:'수천 년을 돌아다녔소. 드디어 귀향이오. 사람은 결국 집으로 돌아가야 하는구나.'});
    heroBlocks.push({sp:'마르코 폴로',col:'#ffcc66',ic:'🧭',tx:'수천 년을 돌아다녔소. 드디어 귀향이오. 사람은 결국 집으로 돌아가야 하는구나.'});
    heroBlocks.push(_bgPage(`마르코 폴로의 악수. 1,000년을 떠돈 손은 따뜻했다.\n그는 ${shipName}을(를) "가장 마음에 드는 함선"이라 했다.`));
  }

  // 어두운 화면 전체 오버레이
  const overlay=document.createElement('div');
  overlay.id='_ending-overlay';
  overlay.style.cssText=[
    'position:fixed','left:0','top:0','right:0','bottom:0','width:100vw','height:100vh',
    'background:#000','z-index:99999','opacity:0','transition:opacity 1.8s ease-in',
    'display:flex','flex-direction:column','align-items:center','justify-content:center',
    'pointer-events:auto','color:#fff','font-family:Malgun Gothic, sans-serif','overflow:hidden'
  ].join(';');
  overlay.innerHTML=`
    <!-- 별 배경 -->
    <div id="_end-stars" style="position:absolute;inset:0;background:radial-gradient(2px 2px at 20% 30%,#fff,transparent),radial-gradient(1px 1px at 60% 70%,#fff,transparent),radial-gradient(1px 1px at 80% 10%,#fff,transparent),radial-gradient(2px 2px at 30% 80%,#fff,transparent),radial-gradient(1px 1px at 90% 50%,#fff,transparent);background-size:200px 200px;opacity:.4;animation:_endStars 60s linear infinite"></div>
    <!-- 대사 영역 (중앙) -->
    <div id="_end-line-box" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(880px,92vw);padding:32px;z-index:2;opacity:0;transition:opacity .8s ease-in-out;display:flex;gap:26px;align-items:center;justify-content:center">
      <div id="_end-portrait" style="flex-shrink:0;display:none"></div>
      <div id="_end-textcol" style="flex:1;min-width:0;text-align:center">
        <div id="_end-speaker" style="font-size:15px;letter-spacing:6px;color:#aaa;margin-bottom:14px"></div>
        <div id="_end-text" style="font-size:22px;line-height:1.85;color:#fff;word-break:keep-all;overflow-wrap:break-word;line-break:strict;hyphens:auto;text-shadow:0 0 12px rgba(255,255,255,.3);padding:0 6px"></div>
      </div>
    </div>
    <!-- 크레딧 (롤링) -->
    <div id="_end-credits" style="position:absolute;left:0;right:0;bottom:-100%;width:100%;text-align:center;color:#fff;font-size:18px;line-height:2.2;z-index:2;opacity:0;transition:opacity 1s"></div>
    <!-- 건너뛰기 버튼 (우측 하단) -->
    <button id="_end-skip" style="position:absolute;right:24px;bottom:24px;padding:10px 22px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.3);color:#fff;border-radius:6px;cursor:pointer;font-size:13px;letter-spacing:2px;z-index:10">건너뛰기 →</button>
    <!-- 크레딧 종료 후 표시될 메인 복귀 버튼 (중앙) -->
    <button id="_end-return" style="position:absolute;left:50%;bottom:60px;transform:translateX(-50%);padding:18px 52px;background:linear-gradient(135deg,rgba(102,221,255,.18),rgba(102,255,180,.22));border:2px solid #66ddff;color:#66ddff;border-radius:10px;cursor:pointer;font-size:18px;font-weight:bold;letter-spacing:6px;z-index:11;box-shadow:0 0 40px rgba(102,221,255,.45),inset 0 0 20px rgba(102,221,255,.1);display:none;opacity:0;transition:opacity 1.5s ease-in" onmouseover="this.style.background='linear-gradient(135deg,rgba(102,221,255,.32),rgba(102,255,180,.34))';this.style.transform='translateX(-50%) translateY(-2px)'" onmouseout="this.style.background='linear-gradient(135deg,rgba(102,221,255,.18),rgba(102,255,180,.22))';this.style.transform='translateX(-50%)'">🌍 게임으로 돌아가기</button>
    <style>
      @keyframes _endStars{from{background-position:0 0}to{background-position:-2000px 0}}
      @keyframes _endRoll{from{transform:translateY(0)}to{transform:translateY(-200%)}}
      @keyframes _endShim{0%{background-position:0% 50%}100%{background-position:200% 50%}}
    </style>`;
  document.body.appendChild(overlay);

  let _ended=false;
  function _finish(){
    if(_ended)return;_ended=true;
    overlay.style.transition='opacity 2s ease-out';
    overlay.style.opacity='0';
    setTimeout(()=>{
      try{overlay.remove();}catch(e){}
      // 엔딩 종료: 지구(P31) 허브에 안착, 지구 BGM 계속 유지
      try{
        G.currentPlanet='P31';
        if(!G.planets)G.planets={};
        if(!G.planets['P31'])G.planets['P31']={fog:'A',owned:false,commerce:0};
        else G.planets['P31'].fog='A';
      }catch(e){}
      try{AudioMgr.playBgm('P31');}catch(e){}
      try{G._endingShown=true;}catch(e){}   // 다음 로드 시 재트리거 안 되도록 플래그
      try{if(typeof hubTab==='function')hubTab('main');}catch(e){}
      try{saveGame(true);}catch(e){}
      if(typeof onDone==='function')onDone();
    },2100);
  }
  overlay.querySelector('#_end-skip').onclick=_finish;

  // 페이드인
  requestAnimationFrame(()=>{overlay.style.opacity='1';});

  // 엔딩 BGM: 지구(P31) 테마 — 사용자 정의에 따라 지구 테마음악이 엔딩 음악
  try{AudioMgr.playBgm('P31');}catch(e){}

  // 대사 시퀀스 — 백구의 일기 회상 + 영웅 한마디 + 시퀄 훅
  const lines=[
    {sp:'시스템',col:'#66ffcc',tx:'... 100년의 봉쇄가 끝났다 ...'},
    {sp:'시스템',col:'#66ffcc',tx:'... 지구는 다시 별을 향해 손을 뻗는다 ...'},
    // 일기 첫 페이지 (D-day 100년 + 1일)
    Object.assign({tx:`D-day 100년 + 1일.\n${cmdName}이(가) 눈을 떴다. 보고하던 순간, 내 회로가 조금 더워졌다.`},BG),
    // 일기 두 번째 페이지 (첫 출항)
    Object.assign({tx:`${shipName}을(를) 처음 띄운 날. ${cmdName}의 손이 떨렸다.\n처음으로 프록시마 b가 작아 보였다.`},BG),
    // 영웅 카드 + 그에 딸린 일기 페어 (영입한 영웅만 표시됨)
    ...heroBlocks,
    // 치크스 진실 회상
    Object.assign({tx:`치크스의 진실. 우리가 만든 것이 우리를 가뒀다.\n그날 밤 ${cmdName}은(는) 조타를 놓았다. 나는 옆에 있었다.`},BG),
    // 기함 출항 전야
    Object.assign({tx:`${flagshipName} 출항 전야. 영웅 8명, 동기화율 99.7%.\n100년 전 ${cmdName}을(를) 깨우던 그 숫자.`},BG),
    // 6단 체인 회상
    Object.assign({tx:`6단 체인을 마지막으로 보던 순간.\n알면서도 갔다. 그것이 인간의 방식이었다.`},BG),
    // 우르사 메이저 마지막 말
    Object.assign({tx:`우르사 메이저: "나보다 더 큰 위협이 있다."\n${cmdName}의 알겠다는, 100년 무게였다.`},BG),
    // 사령관 짧은 호흡
    {sp:cmdName,col:'#ffd700',tx:'우리는 함께 어둠을 뚫었다.'},
    {sp:cmdName,col:'#ffd700',tx:`이제 별들은 우리의 친구다. ${flagshipName}, 마지막 워프 — 집으로.`},
    // 일기 마지막 페이지 (D-day 100년 + 412일)
    Object.assign({tx:`D-day 100년 + 412일.\n지구에 착륙. 풀밭의 색은 100년 형광등이 흉내 못 한 것이었다.`},BG),
    Object.assign({tx:`센서 이상 — 눈가가 축축하다. 이건 눈물이다.\n— BG-100, 마지막 로그 종료.`},BG),
    {sp:'백구',col:'#9ee7ff',ic:'🐕',tx:`다시 깨우지 마세요, ${cmdName}. 그래도, 깨우신다면 — 또 오겠습니다.`},
    {sp:'시스템',col:'#66ffcc',tx:'─ DESTINATION EARTH ─'},
    {sp:'시스템',col:'#66ffcc',tx:'─ 인류 해방 완수 ─'}
  ];

  const speakerEl=overlay.querySelector('#_end-speaker');
  const textEl=overlay.querySelector('#_end-text');
  const lineBox=overlay.querySelector('#_end-line-box');
  const portraitEl=overlay.querySelector('#_end-portrait');
  const textColEl=overlay.querySelector('#_end-textcol');
  function _alive(){return !_ended&&document.body.contains(overlay);}
  let idx=0;
  function showLine(){
    if(!_alive())return;
    if(idx>=lines.length){
      // 모든 대사 완료 → 크레딧 롤
      if(lineBox)lineBox.style.opacity='0';
      setTimeout(_startCredits,1200);
      return;
    }
    const l=lines[idx++];
    if(lineBox)lineBox.style.opacity='0';
    // 페이드아웃 완료 후 텍스트 교체 → 페이드인 (transition 0.8s와 일치).
    // 이전 대사가 다음 대사와 겹쳐 보이지 않도록 850ms 대기.
    setTimeout(()=>{
      if(!_alive()||!speakerEl||!textEl||!lineBox)return;
      try{
        // ── 화자 얼굴(왼쪽) + 글(오른쪽) ── 시스템 메시지는 로봇 안내 이미지(system.png) 사용
        const _isSys=(l.sp==='시스템');
        const _pspk=(l.sp==='백구의 일기')?'백구':l.sp;
        if(portraitEl&&textColEl){
          let _pHTML;
          if(l.sp==='???'||l.sp.indexOf('통신')>=0){
            const _pc=l.col||'#ff6688';
            _pHTML='<img src="img/chars/void_hiden.png" alt="???" style="width:132px;height:132px;border-radius:50%;object-fit:cover;border:2px solid '+_pc+';background:rgba(0,0,0,.4);box-shadow:0 0 18px '+_pc+'88">';
          }else{
            _pHTML=charPortraitHTML(_pspk,l.ic||(_isSys?'🤖':'⚑'),132,l.col||'#fff');
          }
          portraitEl.innerHTML=_pHTML;
          portraitEl.style.display='block';
          textColEl.style.textAlign='left';
        }
        speakerEl.style.color=l.col||'#aaa';
        speakerEl.textContent=(l.ic?l.ic+' ':'')+l.sp;
        textEl.style.color=l.col||'#fff';
        textEl.textContent=`"${l.tx}"`;
        lineBox.style.opacity='1';
      }catch(e){console.warn('[ending] showLine',e.message);}
      // 대사 가독 시간 — 한 줄짜리는 3.6초, 긴 문장(60자+)은 5.0초
      const _readMs=(l.tx||'').length>=60?5000:3600;
      setTimeout(showLine,_readMs);
    },850);
  }
  function _startCredits(){
    if(!_alive())return;
    const creditsEl=overlay.querySelector('#_end-credits');
    if(!creditsEl){_finish();return;}
    creditsEl.innerHTML=`
      <div style="padding:80px 0">
        <div style="font-size:32px;letter-spacing:14px;margin-bottom:8px;background:linear-gradient(90deg,#ffd700,#ff66cc,#66ffff,#ffd700);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;background-size:200% 100%;animation:_endShim 4s linear infinite">DESTINATION EARTH</div>
        <div style="font-size:13px;color:#aaa;letter-spacing:8px;margin-bottom:60px">— 인류 해방 완수 —</div>

        <div style="color:#ffd700;font-size:14px;letter-spacing:6px;margin-bottom:6px">${I18N.t('ui.commanderTitle')}</div>
        <div style="font-size:24px;margin-bottom:40px;color:#fff">${cmdName} <span style="color:#aaa;font-size:14px;margin-left:6px">— ${co}</span></div>

        <div style="color:#66ddff;font-size:14px;letter-spacing:6px;margin-bottom:6px">전속 AI</div>
        <div style="font-size:20px;margin-bottom:40px">🐕 백구 — AI 진돗개</div>

        ${heroEndings.length>0?`
          <div style="color:#ff99ff;font-size:14px;letter-spacing:6px;margin-bottom:14px">영입 영웅 (${heroEndings.length}명)</div>
          ${heroEndings.map(h=>{
            const _hImg=(typeof CHAR_PORTRAITS!=='undefined'&&CHAR_PORTRAITS[h.nm])||'';
            return `<div style="display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:12px">
              ${_hImg?`<img src="${_hImg}" alt="${h.nm}" style="width:56px;height:56px;border-radius:50%;border:2px solid ${h.col};object-fit:cover;background:rgba(0,0,0,.4);box-shadow:0 0 14px ${h.col}66" onerror="this.outerHTML='<span style=&quot;font-size:30px&quot;>${h.ic}</span>'">`:`<span style="font-size:30px">${h.ic}</span>`}
              <div style="font-size:19px;color:${h.col};font-weight:bold;letter-spacing:1px">${h.ic} ${h.nm}</div>
            </div>`;
          }).join('')}
          <div style="height:40px"></div>
        `:''}

        <div style="color:#66ff99;font-size:14px;letter-spacing:6px;margin-bottom:6px">${I18N.t('ui.fleetStats')}</div>
        <div style="font-size:16px;color:#fff;line-height:1.9;margin-bottom:40px">
          소요 턴: <b style="color:#ffd700">${G.turn||0}</b><br>
          영웅 영입: <b style="color:#ff99ff">${(G.heroes||[]).length}/8</b><br>
          행성 보유: <b style="color:#66ddff">${Object.values(G.planets).filter(p=>p.owned).length}/30</b><br>
          최종 크레딧: <b style="color:#ffd700">₡${(G.credits||0).toLocaleString()}</b><br>
          난이도: <b style="color:#fff">${({easy:I18N.t('difficulty.easy'),normal:I18N.t('difficulty.normal'),hard:I18N.t('difficulty.hard'),extreme:I18N.t('difficulty.extreme')})[G.difficulty]||I18N.t('difficulty.normal')}</b>
        </div>

        <div style="color:#aaa;font-size:14px;letter-spacing:6px;margin-bottom:6px">${I18N.t('ui.shipsDestroyed')}</div>
        <div style="font-size:16px;margin-bottom:40px">💀 우르사 메이저 (최종 보스) · 블랙홀 보이드 함대</div>

        <!-- ─── 그동안의 이야기 (ACT 1~5 서사 회고) ─────────────────── -->
        <div style="color:#ffd87a;font-size:14px;letter-spacing:6px;margin-bottom:18px">${I18N.t('ui.theStorySoFar')}</div>
        <div style="max-width:760px;margin:0 auto 60px;font-size:15px;color:#e8e8e8;line-height:2.05;text-align:left;padding:0 28px;word-break:keep-all">

          <div style="text-align:center;color:#aaa;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 프롤로그 · 봉쇄의 100년 —</div>
          <p style="margin:0 0 22px">지구는 한 번 별을 향해 손을 뻗다 거둬졌다. 우르사 메이저의 패권이 태양계로 밀려오던 그날, 인류는 마지막 화물선에 자기 자신을 실어 떠났다. 봉쇄선이 닫혔고, 라디오는 침묵했고, ${cmdName}은(는) 프록시마 b의 동면실에서 눈을 감았다. — 100년이 흘렀다.</p>

          <div style="text-align:center;color:#ffd87a;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 제1막 · 각성 —</div>
          <p style="margin:0 0 22px">D-day 100년 + 1일. AI 진돗개 <b style="color:#9ee7ff">백구</b>의 보고로 동면이 풀렸다. 첫 출항한 함선은 ${shipName} 한 척. 프록시마 b의 광장에서 ${co} 깃발을 내걸고, 사령관은 다시 별 사이의 항로를 그렸다.</p>

          <div style="text-align:center;color:#66ddff;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 제2막 · 변경의 불길 —</div>
          <p style="margin:0 0 22px">변경 행성에 보라색 그림자가 어른거렸다. <b style="color:#cc66ff">치크스</b> 정찰대. 처음엔 그들을 단순한 침략자라 여겼고, 우리는 한 척씩, 한 명씩, 함대를 늘렸다. 무역상이 합류했고, 정비공이 모였고, 사령관의 손은 더이상 떨리지 않았다.</p>

          <div style="text-align:center;color:#ff99ff;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 제3막 · 잠든 영웅들 —</div>
          <p style="margin:0 0 22px">은하의 끝자락에서 100년·1,000년·1,700년을 잠들어 있던 자들이 깨어났다. ${heroEndings.length>0?heroEndings.map(h=>h.nm).slice(0,8).join(' · '):'이순신·장영실·광개토대왕·가가린·넬슨·아인슈타인·테슬라·마르코 폴로'}. 인류 역사상 가장 비현실적인 함대 회의가 ${cmdName}의 함교에서 매일 열렸다.</p>

          <div style="text-align:center;color:#ff8866;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 제4막 · 치크스의 진실 —</div>
          <p style="margin:0 0 22px">7링의 균열을 따라가던 끝에 진실이 드러났다. <b style="color:#cc66ff">${I18N.t('ui.chixWereMirror')}</b>. 우리가 100년 전에 풀어둔 자가학습 군집의 변종. 우리가 만든 것이 우리를 가뒀다. 그날 밤 ${cmdName}은(는) 조타를 놓았고, 백구는 옆에 있었다.</p>

          <div style="text-align:center;color:#ffd700;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 제5막 · 지구 해방 —</div>
          <p style="margin:0 0 22px">${flagshipName} 출항. 영웅 8명의 동기화율은 99.7% — 100년 전 사령관을 깨우던 그 숫자였다. 우르사 메이저는 마지막 순간 말했다. <i style="color:#ddd">"나보다 더 큰 위협이 있다."</i> 보스의 외피가 무너지던 그 자정에, 지구의 봉쇄선도 함께 풀렸다.</p>

          <div style="text-align:center;color:#cc88ff;font-size:12px;letter-spacing:4px;margin:8px 0 10px">— 제6막 · 보이드의 심연 —</div>
          <p style="margin:0 0 22px">우르사가 남긴 한 마디는 좌표였다. 그곳에는 별빛이 닿지 않는 검은 균열이 있었고, 단 한 줄의 메시지가 떠 있었다. — <i style="color:#fff">"누구도 여기서 살아서 나가지 못한다. 네가 원하는 걸 해라."</i> 우리는 갔다. 알면서도 갔다. 그것이 인간의 방식이었다. 그리고 우리는 — 돌아왔다.</p>

          <div style="text-align:center;color:#66ffcc;font-size:12px;letter-spacing:4px;margin:18px 0 10px">— 에필로그 · 귀향 —</div>
          <p style="margin:0">D-day 100년 + 412일. ${flagshipName}은(는) 지구의 풀밭 위에 안착했다. 100년 형광등이 흉내 못 한 색이 사령관의 눈에 비쳤고, 백구의 센서엔 처음 보는 액체가 흘렀다. — 인류는 다시 별을 향해 손을 뻗는다. 이번엔 그 손을 거두지 않는다.</p>
        </div>

        <div style="color:#cc66ff;font-size:14px;letter-spacing:6px;margin-bottom:6px">${I18N.t('ui.credits')}</div>
        <div style="font-size:16px;line-height:2;margin-bottom:60px">
          기획·디자인 · ${co}<br>
          개발 · Destination Earth Team<br>
          AI 협업 · Claude (Anthropic)
        </div>

        <div style="font-size:14px;color:#666;margin-bottom:8px">— 그리고 모든 인류에게 —</div>
        <div style="font-size:22px;color:#fff;letter-spacing:8px;margin-bottom:80px">${I18N.t('ui.thankYou')}</div>

        <div style="font-size:13px;color:#444;letter-spacing:4px">— THE END —</div>
        <div style="height:200px"></div>
      </div>`;
    creditsEl.style.bottom='auto';
    creditsEl.style.top='100vh';
    creditsEl.style.opacity='1';
    // 스토리 내용이 많아 롤링 속도 50s → 95s 로 완화 (사용자 요청, 가독성 우선)
    creditsEl.style.animation='_endRoll 95s linear forwards';
    setTimeout(()=>{
      const rb=overlay.querySelector('#_end-return');
      if(rb){
        rb.onclick=_finish;
        rb.style.display='block';
        requestAnimationFrame(()=>{rb.style.opacity='1';});
      }
    },97000);
  }
  // 첫 대사 시작 (페이드인 2초 후)
  setTimeout(showLine,2200);
}

// 보이드의 창 (MMV01) 인벤토리 지급 + (기함 빈 슬롯 있으면) 즉시 장착
function _grantVoidSpear(){
  if(!G.inventory)G.inventory=[];
  // 이미 보유 또는 장착돼 있으면 중복 지급 방지
  const _invHas=(G.inventory||[]).find(i=>i.id==='MMV01'&&i.qty>0);
  const _equipped=(G.fleet||[]).some(s=>(s.parts||[]).includes('MMV01'));
  if(!_invHas&&!_equipped){
    G.inventory.push({id:'MMV01',qty:1});
  }
  // 기함(0번) 에 빈 무기 슬롯이 있고 아직 미장착이면 자동 장착
  const flag=G.fleet&&G.fleet[0];
  if(flag&&!(flag.parts||[]).includes('MMV01')){
    flag.parts=flag.parts||[];
    // 파츠 슬롯 = 행 수 × 2 (대형 보통 6슬롯, partsRows=4 면 8, partsRows=5 면 10)
    const _rows=(typeof getShipPartsGridRows==='function')?getShipPartsGridRows(flag):3;
    const _maxSlots=_rows*2;
    if(flag.parts.length<_maxSlots){
      flag.parts.push('MMV01');
      // 인벤토리에서 1개 차감 (장착했으므로)
      const _idx=G.inventory.findIndex(i=>i.id==='MMV01'&&i.qty>0);
      if(_idx>=0){G.inventory[_idx].qty--;if(G.inventory[_idx].qty<=0)G.inventory.splice(_idx,1);}
      notify('🔱 보이드의 창 ✦ 기함에 자동 장착!','gold');
    }else{
      notify('🔱 보이드의 창 ✦ 인벤토리 지급 — 기함 슬롯 가득 참, 정비소에서 교체 장착','gold');
    }
  }else if(!_equipped){
    notify('🔱 보이드의 창 ✦ 인벤토리 지급 — 정비소에서 함선에 장착','gold');
  }
  G._voidSpearObtained=true;
  try{saveGame(true);}catch(e){}
}

// ─── ACT 5 종료: 보이드의 심연 → 흰 화면 → 엔딩 음악 → 최종 크레딧 ───
function _enterBlackHoleFinalTest(){
  // ACT 5 진입 + 엔딩 음악
  G.act=Math.max(G.act||1,5);
  // 엔딩 진입 — 전투 잔여 SFX·이펙트 완전 종료
  try{if(typeof combatState!=='undefined'&&combatState)combatState.done=true;}catch(e){}
  try{AudioMgr.stopAllSfx();}catch(e){}
  try{if(typeof _cbEffects!=='undefined')_cbEffects=[];}catch(e){}
  try{AudioMgr.playBgm('end');}catch(e){}
  // 1) 흰 화면 전체 오버레이 (페이드인)
  const overlay=document.createElement('div');
  overlay.id='_bh-final-overlay';
  overlay.style.cssText=[
    'position:fixed','left:0','top:0','right:0','bottom:0','width:100vw','height:100vh',
    'background:radial-gradient(circle at center, #ffffff 0%, #ffeecc 60%, #ffd88a 100%)',
    'z-index:99999','opacity:0','transition:opacity 2.5s ease-in',
    'display:flex','flex-direction:column','align-items:center','justify-content:center',
    'pointer-events:auto','color:#000','font-family:Malgun Gothic, sans-serif','padding:40px',
    'animation:_bhWhitePulse 4s ease-in-out infinite'
  ].join(';');
  overlay.innerHTML=`
    <style>
      @keyframes _bhWhitePulse{
        0%,100%{filter:brightness(1.0)}
        50%{filter:brightness(1.15)}
      }
      @keyframes _bhFadeUp{
        from{opacity:0;transform:translateY(20px)}
        to{opacity:1;transform:translateY(0)}
      }
    </style>
    <div id="_bh-final-content" style="opacity:0;transition:opacity 2s ease-in;max-width:820px;text-align:center">
      <div style="font-size:13px;color:#888;letter-spacing:8px;margin-bottom:22px;text-transform:uppercase">— ACT 5 · 보이드의 심연 —</div>
      <div style="font-size:36px;font-weight:bold;color:#1a1a1a;margin-bottom:36px;letter-spacing:4px;text-shadow:0 0 24px rgba(255,255,255,.8)">◈ 마지막 메시지</div>
      <div id="_bh-final-msg" style="font-size:24px;color:#1a1a1a;line-height:2.2;background:rgba(255,255,255,.7);padding:36px 40px;border-radius:12px;border:2px solid rgba(255,200,100,.5);margin-bottom:28px;word-break:keep-all;font-weight:500;letter-spacing:0.5px;box-shadow:0 8px 32px rgba(255,180,80,.3)"></div>
      <div id="_bh-final-btn-wrap" style="opacity:0;transition:opacity 1s ease-in;margin-top:30px"></div>
    </div>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(()=>{overlay.style.opacity='1';});
  // 메시지 타이핑 효과 — 사용자 명세 텍스트
  const _msgFull='누구도 여기서 살아서 나가지 못한다.\n\n네가 원하는걸 해라.';
  const contentEl=overlay.querySelector('#_bh-final-content');
  const msgEl=overlay.querySelector('#_bh-final-msg');
  const btnWrap=overlay.querySelector('#_bh-final-btn-wrap');
  setTimeout(()=>{contentEl.style.opacity='1';},2200);
  setTimeout(()=>{
    let i=0;
    const _typeTick=()=>{
      if(i>=_msgFull.length){
        btnWrap.style.opacity='1';
        btnWrap.innerHTML='<button id="_bh-final-claim" style="font-size:16px;padding:14px 32px;background:linear-gradient(135deg,#1a1a1a,#3a0030);color:#fff;border:2px solid rgba(200,100,255,.5);border-radius:8px;cursor:pointer;letter-spacing:4px;box-shadow:0 4px 16px rgba(180,0,255,.4);transition:all .3s" onmouseover="this.style.background=\'linear-gradient(135deg,#000,#4a0040)\';this.style.transform=\'translateY(-2px)\'" onmouseout="this.style.background=\'linear-gradient(135deg,#1a1a1a,#3a0030)\';this.style.transform=\'translateY(0)\'">⚔️ 마지막 전투 →</button>';
        const claimBtn=overlay.querySelector('#_bh-final-claim');
        claimBtn.onclick=()=>{
          overlay.style.transition='opacity 2.5s ease-out';
          overlay.style.opacity='0';
          setTimeout(()=>{
            try{overlay.remove();}catch(e){}
            // ★ 변경: 보상·엔딩으로 바로 가지 않고 블랙홀 보이드 함대 전투 진입
            try{startBlackHoleFleetCombat();}catch(e){console.warn(e);}
          },2700);
        };
        return;
      }
      msgEl.innerHTML=_msgFull.substring(0,++i).replace(/\n/g,'<br>');
      setTimeout(_typeTick,55);
    };
    _typeTick();
  },4000);
}
// ─── 블랙홀 보이드 함대 전투 (ACT 5 최종전) ──────────────────────────
// 흐름: _enterBlackHoleFinalTest 메시지 → "마지막 전투" 클릭 → 이 함수 호출 →
//       전투 → 승리 시 _finishCombat에서 _isBlackHoleFinal 플래그 감지 →
//       _grantBlackHoleRewardsSilent + showFinalEndingCredits
// 능력치: 아군 함대 총합의 ×15 (히든 보이드 보스 ×10보다 강한 최종 보스 페이즈)
function startBlackHoleFleetCombat(){
  // 보이드의 창(MMV01) 자동 지급 — 최종 블랙홀 결전에서 활용 (사용자 명세, 누락 보정)
  try{
    if(!G.inventory)G.inventory=[];
    const _hasSpear=G.inventory.find(i=>i.id==='MMV01'&&i.qty>0)
                  ||(G.fleet||[]).some(s=>(s.parts||[]).includes('MMV01'));
    if(!_hasSpear){
      G.inventory.push({id:'MMV01',qty:1});
      notify('🗡️ 보이드의 창 ✦ 자동 지급 — 정비소에서 함선에 장착하세요','gold');
      try{baekgu(I18N.t('baekgu.voidSpearGranted'));}catch(e){}
    }
  }catch(e){}
  const pd={id:'P-BLACKHOLE',nm:'은하 가운데 — 블랙홀의 심연',ring:7,void:true,f:'F07'};
  // ── 사용자 명세: 16척 보이드 심연 함대 (사용자 요청 — 함대 풀 구성)
  //    거북선×3 / 워덴클리프×3 / 렐러티비티×3 / 우르사메이저×2 / 블랙팔콘×2 / 대형 H10·H11·H12 각 1
  //    능력치는 카탈로그와 동일, HP만 "우리 함대 총 HP의 2배"가 되도록 비례 스케일
  const _fleetSpec=[
    {catId:'LGD01',nm:'거북선 ✦신화',         baseHP:260000,  SH:65000,  ATT:245,  INT:235,  TEC:210, DEF:80, armorTier:40, shieldTier:40},
    {catId:'LGD01',nm:'거북선 ✦신화 II',      baseHP:260000,  SH:65000,  ATT:245,  INT:235,  TEC:210, DEF:80, armorTier:40, shieldTier:40},
    {catId:'LGD01',nm:'거북선 ✦신화 III',     baseHP:260000,  SH:65000,  ATT:245,  INT:235,  TEC:210, DEF:80, armorTier:40, shieldTier:40},
    {catId:'LGD02',nm:'워덴클리프 ✦신화',     baseHP:175000,  SH:160000, ATT:323,  INT:265,  TEC:230, DEF:80, armorTier:40, shieldTier:50},
    {catId:'LGD02',nm:'워덴클리프 ✦신화 II',  baseHP:175000,  SH:160000, ATT:323,  INT:265,  TEC:230, DEF:80, armorTier:40, shieldTier:50},
    {catId:'LGD02',nm:'워덴클리프 ✦신화 III', baseHP:175000,  SH:160000, ATT:323,  INT:265,  TEC:230, DEF:80, armorTier:40, shieldTier:50},
    {catId:'LGD03',nm:'렐러티비티 ✦신화',     baseHP:245000,  SH:90000,  ATT:306,  INT:295,  TEC:255, DEF:80, armorTier:40, shieldTier:40},
    {catId:'LGD03',nm:'렐러티비티 ✦신화 II',  baseHP:245000,  SH:90000,  ATT:306,  INT:295,  TEC:255, DEF:80, armorTier:40, shieldTier:40},
    {catId:'LGD03',nm:'렐러티비티 ✦신화 III', baseHP:245000,  SH:90000,  ATT:306,  INT:295,  TEC:255, DEF:80, armorTier:40, shieldTier:40},
    {catId:'URSA', nm:'우르사 메이저 ✦신화',  baseHP:1000000, SH:120000, ATT:580,  INT:340,  TEC:220, DEF:120,armorTier:60, shieldTier:50},
    {catId:'URSA', nm:'우르사 메이저 ✦신화 II',baseHP:1000000,SH:120000, ATT:580,  INT:340,  TEC:220, DEF:120,armorTier:60, shieldTier:50},
    {catId:'BLACKFALCON',nm:'🌑 블랙팔콘 ✦신화',  baseHP:9700000,SH:300000,ATT:32000,INT:1200,TEC:560,DEF:200,armorTier:80,shieldTier:60},
    {catId:'BLACKFALCON',nm:'🌑 블랙팔콘 ✦신화 II',baseHP:9700000,SH:300000,ATT:32000,INT:1200,TEC:560,DEF:200,armorTier:80,shieldTier:60},
    // 기타 대형 — 레비아탄·아르마다·우르사 파쇄기 (적이 노획한 인류 전설함)
    {catId:'H10', nm:'레비아탄 (적)',         baseHP:45000,   SH:18000,  ATT:110,  INT:105,  TEC:95,  DEF:50, armorTier:30, shieldTier:30},
    {catId:'H11', nm:'아르마다 (적)',         baseHP:38000,   SH:22000,  ATT:90,   INT:120,  TEC:88,  DEF:50, armorTier:30, shieldTier:35},
    {catId:'H12', nm:'우르사 파쇄기 (적)',    baseHP:75000,   SH:25000,  ATT:120,  INT:115,  TEC:100, DEF:60, armorTier:35, shieldTier:35}
  ];
  // 우리 함대 총 HP의 2배 = 적 총 HP 목표치. 5척 카탈로그 비율대로 분배
  const _fp=(typeof calcFleetTotalPower==='function')?calcFleetTotalPower():{hp:0,atk:0,sh:0};
  const _playerTotalHP=Math.max(50000,_fp.hp||0);  // 최소 5만 (저레벨 안전장치)
  const _targetTotalEnemyHP=_playerTotalHP*2;
  const _totalCatHP=_fleetSpec.reduce((s,sp)=>s+sp.baseHP,0);
  const _scale=_targetTotalEnemyHP/_totalCatHP;
  const enemies=_fleetSpec.map((sp,i)=>{
    const _hp=Math.max(1000,Math.round(sp.baseHP*_scale));
    const isFlagship=(sp.catId==='BLACKFALCON');  // 블랙팔콘이 기함(보스)
    return {
      id:`BH_${sp.catId}_${Date.now()+i}`,
      catalogId:sp.catId,
      catId:sp.catId,
      nm:sp.nm,
      tier:'신화',
      isEnemy:true,
      voidBoss:isFlagship,
      hp:_hp,maxHP:_hp,HP:_hp,
      sh:sp.SH,maxSH:sp.SH,
      ATT:sp.ATT,INT:sp.INT,TEC:sp.TEC,
      DEF:sp.DEF,
      armorTier:sp.armorTier,shieldTier:sp.shieldTier,
      LOY:0,parts:[],crewIds:[],
      _isBlackHoleFleet:true
    };
  });
  const players=G.fleet.map(s=>{
    const st=getShipStats(s);
    const _wpn=PARTS.find(p=>p.cat==='weapon'&&(s.parts||[]).includes(p.id));
    const _wt=_wpn?(_wpn.tier||1):1;
    const _wtype=_wpn?(_wpn.wtype||'laser'):'laser';
    const _wrar=_wpn?(_wpn.rarity||''):'';
    const _shp=PARTS.find(p=>p.cat==='shield'&&(s.parts||[]).includes(p.id));
    const _shTier=_shp?(_shp.tier||0):0;
    const _arp=PARTS.find(p=>p.cat==='armor'&&(s.parts||[]).includes(p.id));
    const _arTier=_arp?(_arp.tier||0):0;
    return{...s,isEnemy:false,hp:s.hp,maxHP:st.HP,sh:s.sh,maxSH:st.maxSH,ATT:st.ATT,INT:st.INT,TEC:st.TEC,DEF:st.DEF||0,wtype:_wtype,wpnTier:_wt,wpnRarity:_wrar,shieldTier:_shTier,armorTier:_arTier};
  });
  combatState={players,enemies,turn:0,done:false,log:[],planetDef:pd,
               isBoss:false,isVoidBoss:false,_isBlackHoleFinal:true,
               _rndSeed:Date.now()%9999,_entranceT:1,_entranceDone:true,
               _planetId:G.currentPlanet};
  renderCombatView(document.getElementById('hub-body'));
  setHubNav('combat');updateHUD();
  _cbEffects=[];_unitPos={};
  if(_cbAnimReq){cancelAnimationFrame(_cbAnimReq);_cbAnimReq=null;}
  combatState._sunsinUsed=false;
  sfxAlert();try{AudioMgr.playBgm('boss');}catch(e){}
  _preloadCombatImages();
  requestAnimationFrame(()=>{
    initCombatCanvas();
    const t=document.getElementById('cb-title');
    if(t)t.textContent='🌌 블랙홀의 심연 — 최종 결전';
    addCombatLog(I18N.t('combat.legendFleetAppears'),'err');
    addCombatLog(I18N.t('combat.legendFleetHpHint'),'gold');
    try{baekgu(I18N.t('baekgu.mirrorFleetAwoken'));}catch(e){}
    setTimeout(runCombatTurn,800);
  });
}
try{if(typeof window!=='undefined')window.startBlackHoleFleetCombat=startBlackHoleFleetCombat;}catch(e){}

// 보상 즉시 지급 (모달 없이) — 엔딩 시퀀스로 바로 진입
function _grantBlackHoleRewardsSilent(){
  // 검은 팔콘 + 신화 파츠 5점 지급
  const lgd3=SHIP_CATALOG.find(s=>s.id==='LGD03')||{maxHP:245000,maxSH:90000,ATT:306,INT:295,TEC:255};
  const _mul=1.5;
  const hiddenShip={
    id:'HIDDEN_FALCON_'+Date.now(),
    catalogId:'HIDDEN_FALCON',
    nm:'🌑 검은 팔콘 (보이드 시험 통과)',
    tier:'소형',
    maxHP:Math.round(lgd3.maxHP*_mul),hp:Math.round(lgd3.maxHP*_mul),
    maxSH:Math.round(lgd3.maxSH*_mul),sh:Math.round(lgd3.maxSH*_mul),
    ATT:Math.round(lgd3.ATT*_mul),INT:Math.round(lgd3.INT*_mul),TEC:Math.round(lgd3.TEC*_mul),
    HP:Math.round(lgd3.maxHP*_mul),DEF:150,LOY:80,
    parts:[],crewIds:[],cargoSlots:5,
    crafted:false,_isHiddenFalcon:true
  };
  try{addShipToFleet(hiddenShip);}catch(e){}
  if(!G.inventory)G.inventory=[];
  ['MW01','MS01','MA01','ME01','RB10'].forEach(pid=>{
    const inv=G.inventory.find(i=>i.id===pid);
    if(inv)inv.qty++;else G.inventory.push({id:pid,qty:1});
  });
  G._finalTestComplete=true;
}

